#include <bits/stdc++.h>
using namespace std;
const int MAX=270005;
int n,m,k,mod;
int f[19][MAX];
vector<long long> g;
int bit_count[MAX];

int adjust(int x){
    if(x<0) return x+mod;
    if(x>=mod) return x-mod;
    return x;
}

void update_value(int &x, int y){
    x=adjust(x+y);
}

int bin_pow(int base,int exp){
    int res=1;
    while(exp){
        if(exp&1) res=1LL*res*base%mod;
        base=1LL*base*base%mod;
        exp>>=1;
    }
    return res;
}

int factorial[MAX], inv_factorial[MAX];

void precompute_factorials(int n){
    factorial[0]=1;
    for(int i=1;i<=n;i++) factorial[i]=1LL*factorial[i-1]*i%mod;
    inv_factorial[n]=bin_pow(factorial[n],mod-2);
    for(int i=n-1;i>=0;i--) inv_factorial[i]=1LL*inv_factorial[i+1]*(i+1)%mod;
}

void transform_array(int *arr,int size,int h){
    for(int p=1; p<size; p<<=1)
        for(int i=0; i<size; i+=p<<1)
            for(int k=i; k<i+p; k++)
                update_value(arr[k+p], h*arr[k]);
}

int l;
vector<long long> operator*(vector<long long> &A, vector<long long> &B){
    static vector<long long> C; C.clear(); C.resize(l+1);
    for(int i=0; i<=l; i++)
        for(int j=0; j<=l-i; j++)
            C[i+j]+=A[i]*B[j];
    for(int i=0; i<=l; i++) C[i]%=mod;
    return C;
}

vector<long long> power_series(vector<long long> A, int k){
    static vector<long long> C; C.clear(); C.resize(l+1);
    C[0]=1;
    while(k){
        if(k&1) C=C*A;
        A=A*A;
        k>>=1;
    }
    return C;
}

int main(){
#ifdef pig
    freopen("C.in","r",stdin);
    freopen("C.out","w",stdout);
#endif
    cin>>n>>k>>mod;
    precompute_factorials(n);
    if(n&1){
        cout<<bin_pow(k,n);
        return 0;
    }
    m=1; while(m<=n) m<<=1; l++;
    for(int i=0; i<m; i++) bit_count[i]=__builtin_popcount(i);
    precompute_factorials(m);
    for(int i=0; i<m; i++){
        f[bit_count[i]][i]=inv_factorial[i];
    }
    for(int i=0; i<l; i++) transform_array(f[i], m, 1);
    g.resize(l+1);
    for(int s=0; s<m; s++){
        for(int i=0; i<=l; i++) g[i]=f[i][s];
        g=power_series(g,k);
        for(int i=0; i<=l; i++) f[i][s]=g[i];
    }
    transform_array(f[bit_count[n]], m, -1);
    cout<<adjust(bin_pow(k,n)-1LL*f[bit_count[n]][n]*factorial[n]%mod);
    return 0;
}
